const axios = require("axios");

const BASE_URI = "http://localhost:5000/api/auth";

// Helper to get headers with token from localStorage
const getAuthHeaders = () => {
  const token = localStorage.getItem("token");
  return {
    headers: {
      headers: { "Content-Type": "application/json" },
      Authorization: token ? `Bearer ${token}` : "",
    },
  };
};

// Register API
exports.register = async (userData) => {
  try {
    const response = await axios.post(`${BASE_URI}/api/auth/register`, userData);
    return response.data;
  } catch (error) {
    console.error("Register error:", error.response?.data || error.message);
    throw error;
  }
};

// Login API
exports.login = async (credentials) => {
  try {
    const response = await axios.post(`${BASE_URI}/api/auth/login`, credentials, getAuthHeaders());
    return response.data;
  } catch (error) {
    console.error("Login error:", error.response?.data || error.message);
    throw error;
  }
};
